import SwiftUI

struct ContentView: View {
    @AppStorage("reaCounter") private var count = 0

    var body: some View {
        VStack(spacing: 20) {
            Text("REA B01")
                .font(.largeTitle.bold())
                .accessibilityAddTraits(.isHeader)

            Text("Počítadlo: \(count)")
                .font(.title2)
                .monospacedDigit()

            Button("Přidat 1") {
                count += 1
            }
            .buttonStyle(.borderedProminent)
        }
        .padding()
    }
}
